QUESTIONS.forEach((q,i)=>q.id="q"+i);
// Series label derivation is generic across every paper in the bank, not just
// Paper 1: each question may carry its own paperNum/sitting; when absent
// (the original Paper 1 questions), we fall back to the number embedded in
// the paper field and "Summer 2017" so existing behaviour is unchanged.
// Crossover questions get three variants rather than one fixed string,
// since which one belongs on screen depends on which tier is currently
// selected: viewing under Foundation should read like any other
// Foundation question (just its own paper/number), viewing under Higher
// the same but for the Higher side, and only the dedicated Crossover tier
// (or the unfiltered "All" view, where no single paper's perspective is
// the obviously right default) shows both numbers paired together.
QUESTIONS.forEach(q=>{
  const paperNumMatch = q.paper && q.paper.match(/Paper (\d)/);
  const pnum = q.paperNum || (paperNumMatch ? paperNumMatch[1] : '1');
  const sitting = q.sitting || 'Summer 2017';
  if(q.tier==="Crossover"){
    q.seriesFoundation = `${sitting} · Paper ${pnum}F`;
    q.seriesHigher = `${sitting} · Paper ${pnum}H`;
    q.series = `${sitting} · Paper ${pnum}F Q${q.n} & ${pnum}H Q${q.higherN}`;
  }
  else if(q.tier==="Higher") q.series=`${sitting} · Paper ${pnum}H`;
  else q.series=`${sitting} · Paper ${pnum}F`;
});


const VULGAR_FRACTIONS = {
  '½':[1,2],'¼':[1,4],'¾':[3,4],'⅓':[1,3],'⅔':[2,3],
  '⅕':[1,5],'⅖':[2,5],'⅗':[3,5],'⅘':[4,5],
  '⅙':[1,6],'⅚':[5,6],'⅛':[1,8],'⅜':[3,8],'⅝':[5,8],'⅞':[7,8]
};
function formatMarkscheme(text){
  // Each new mark-awarding code (P1, M1, A1, B2, C1, SC, NB...) starts its
  // own line, and so does each new part label ((b), (c), (ii)...). Only
  // breaks after sentence-ending punctuation, not any space, so a
  // backreference like "(dep on P2)" mid-sentence isn't mistaken for a
  // new mark starting.
  return String(text).replace(
    /([.;:])\s+(?=\([a-z]\)|\((?:i|ii|iii|iv|v)\)|[PMABC]\d+\b|SC\b|NB\b)/g,
    '$1\n'
  );
}

function formatSqrt(text){
  // Plain "√" is just a checkmark glyph with a short built-in stub - it
  // doesn't extend a line over whatever follows, so a multi-character
  // radicand (√(5²+12²)) reads as disconnected from the root sign rather
  // than "everything here is under the root". A CSS overline is added over
  // the actual radicand instead. Parenthesised radicands drop their visible
  // brackets, since the overline itself now marks where the root ends.
  let str = String(text);
  str = str.replace(/√\(([^()]+)\)/g, '√<span class="radicand">$1</span>');
  str = str.replace(/√([0-9a-zA-Z¹²³⁰]+)/g, '√<span class="radicand">$1</span>');
  return str;
}

function mathText(text){
  return stackFraction(formatSqrt(text));
}
function mathMarkscheme(text){
  return stackFraction(formatSqrt(formatMarkscheme(text)));
}

function stackFraction(text){
  // Applied per line (not to the whole field at once): a fraction sitting
  // alone in a short expression ("Solve x/5 = 2½") reads better full-size,
  // but the same full-size fraction embedded mid-sentence in a longer,
  // wordy line ("...rate of overtime pay per hour is 1¼ times...") pushes
  // that line's height up noticeably more than its neighbours. Lines over
  // ~40 characters get the compact fraction style instead so the jump is
  // barely noticeable; short, mostly-mathematical lines keep the larger,
  // easier-to-read fraction.
  return String(text).split('\n').map(line => {
    // Measured on the visible text only - a line with pre-embedded markup
    // (e.g. a manually-built exponent) shouldn't be miscounted as "long
    // and wordy" just because of its HTML, which would wrongly shrink an
    // unrelated auto-detected fraction on the same line.
    const visibleLength = line.replace(/<[^>]+>/g, '').length;
    const cls = visibleLength > 40 ? 'frac-sm' : 'frac';
    let str = line;
    str = str.replace(/([0-9]*)([½¼¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞])/g, (m, whole, frac) => {
      const [n,d] = VULGAR_FRACTIONS[frac];
      return (whole||'') + `<span class="${cls}"><span class="num">${n}</span><span class="den">${d}</span></span>`;
    });
    // Compound fractions where at least one side is a parenthesised
    // expression, e.g. a rearranged-formula answer like "(T - 3)/4" or
    // "15t/(w + 30)". Tolerates one level of nested brackets inside the
    // outer pair (eg a denominator like "x(x+1)(x-2)") - anything nested
    // deeper than that (eg a quadratic-formula surd) just won't match here
    // and is left as plain text, same as before this fix existed. Must run
    // before the plain-token pattern below, since that pattern's character
    // class doesn't include "(" or ")" or spaces and so never matches these
    // on its own. Same digit-somewhere guard as the plain-token pattern,
    // since this also runs on ordinary question text that can contain
    // "and/or"-style slashes.
    {
      const BAL = '\\((?:[^()]|\\([^()]*\\))+\\)';
      const re = new RegExp('(' + BAL + '|[a-zA-Z0-9¹²³⁰]+)\\s*\\/\\s*(' + BAL + '|[a-zA-Z0-9¹²³⁰]+)', 'g');
      str = str.replace(re, (m, num, den) => {
        if (num[0] !== '(' && den[0] !== '(') return m; // plain token/token - leave for the next pass
        if (!/\d/.test(num) && !/\d/.test(den)) return m;
        const stripNum = num[0]==='(' ? num.slice(1,-1).trim() : num;
        const stripDen = den[0]==='(' ? den.slice(1,-1).trim() : den;
        return `<span class="${cls}"><span class="num">${stripNum}</span><span class="den">${stripDen}</span></span>`;
      });
    }
    // Require at least one side to contain a digit, so word/word patterns
    // that just happen to use "/" to mean "or" (e.g. "rolls/ketchup",
    // "and/or") aren't mistaken for a mathematical fraction like "9/x²".
    // A side made up purely of letters (no digits) is always an algebraic
    // term here, so it's italicised automatically - this has to happen
    // inside this same regex, not as a separate pass, because wrapping a
    // variable in <em> before this runs would break the direct adjacency
    // ("x" immediately next to "/") that the match depends on.
    str = str.replace(/\b([a-zA-Z0-9¹²³⁰]+)\/([a-zA-Z0-9¹²³⁰]+)\b/g, (m, num, den) => {
      if (!/\d/.test(num) && !/\d/.test(den)) return m;
      const wrapNum = /^[a-zA-Z¹²³⁰]+$/.test(num) ? `<em>${num}</em>` : num;
      const wrapDen = /^[a-zA-Z¹²³⁰]+$/.test(den) ? `<em>${den}</em>` : den;
      return `<span class="${cls}"><span class="num">${wrapNum}</span><span class="den">${wrapDen}</span></span>`;
    });
    return str;
  }).join('\n');
}

// Only Papers 2 & 3 allow a calculator - Paper 1 is always non-calculator,
// and its paper string ("Paper 1 (non-calculator)") also contains the
// substring "calculator", so checking for the absence of "non-calculator"
// is the reliable test rather than checking for the presence of "calculator".
function isCalculatorPaper(q){
  return !!q.paper && q.paper.indexOf('non-calculator')===-1;
}
const CALC_SVG='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="2" width="16" height="20" rx="2"></rect><rect x="7" y="5" width="10" height="4" rx="0.5"></rect><rect x="7" y="12" width="2.5" height="2.5"></rect><rect x="10.75" y="12" width="2.5" height="2.5"></rect><rect x="14.5" y="12" width="2.5" height="2.5"></rect><rect x="7" y="16" width="2.5" height="2.5"></rect><rect x="10.75" y="16" width="2.5" height="2.5"></rect><rect x="14.5" y="16" width="2.5" height="2.5"></rect></svg>';
// Deliberately returns nothing for non-calculator questions - see the
// .calc-icon comment in <style> for why the absence of an icon is the
// intended "no calculator" signal, rather than a crossed-out icon.
function calcIconHTML(q){
  return isCalculatorPaper(q) ? `<span class="calc-icon" title="Calculator allowed" aria-label="Calculator allowed">${CALC_SVG}</span>` : '';
}

function sourceTag(q){
  if(q.tier==="Crossover"){
    if(state.tier==="Foundation") return `${q.seriesFoundation} · Q${q.n}`;
    if(state.tier==="Higher") return `${q.seriesHigher} · Q${q.higherN}`;
    return q.series; // Crossover tier, or unfiltered "All" - show both
  }
  return `${q.series} · Q${q.n.replace('H','')}`;
}

// When viewing the Higher paper on its own, crossover questions must show
// their Higher-paper number (e.g. "1") rather than the Foundation number
// they're stored under (e.g. "21"), so the list reads 1, 2, 3... in order.
function displayN(q){
  if(state.tier==="Higher" && q.higherN) return q.higherN;
  return q.n.replace('H','');
}
function sortKey(q){
  const raw = displayN(q);
  const m = raw.match(/^(\d+)/);
  return [m ? parseInt(m[1],10) : 0, raw];
}


function questionHeaderHTML(q){
  return `
    <div class="modal-header-top">
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
        <span class="subtopic-pill">${q.subtopic}</span>
        <span class="source-tag">${sourceTag(q)}</span>
      </div>
      <div class="card-top-right">
        ${calcIconHTML(q)}
        <span class="marks-badge">${q.marks} mark${q.marks>1?'s':''}</span>
      </div>
    </div>
  `;
}

// Cropped-from-PDF questions (q.qimg present) replace intro/svg/text with a
// single image of the original paper, shown at a FIXED multiple of its
// native pixel size everywhere - 0.5x in the grid card, a larger 0.75x in
// the modal (which has more room) - never stretched to fill a container,
// so every question's printed text renders at the same on-screen size
// regardless of that particular crop's own width or aspect ratio.
const MODAL_CROP_SCALE = 0.75;
function baseQuestionNumber(q){
  const m = displayN(q).match(/^\d+/);
  return m ? m[0] : displayN(q);
}
// Base path for the linked question-crop images under assets/images/ on the
// real site. All questions (Summer 2017 and later) now use this - there
// are no more embedded base64 images left in the data.
const QIMG_BASE_PATH = "/assets/images/gcse-question-bank/";
// Crossover questions can carry up to three separate crops of the SAME
// question content, differing only in which (if any) printed question
// number is baked into the image pixels:
//   q.qimg          - Foundation-paper crop, Foundation number baked in
//   q.higherQimg     - Higher-paper crop, Higher number baked in
//   q.crossoverQimg  - either paper's crop with the number masked out,
//                       used when neither number is the "right" one to
//                       show (the Crossover tier view)
// Non-crossover questions only ever have q.qimg, so this falls through
// to that in every other case. higherQimg falling back to qimg (rather
// than the reverse) is deliberate: until every crossover question has
// its own Higher-paper crop, showing the Foundation crop under Higher
// tier is the same behaviour the site already had, not a regression.
function selectQimg(q){
  if(state.tier==="Higher" && q.higherQimg) return q.higherQimg;
  // Crossover tier and the unfiltered "all" view both show the
  // number-masked crop: under "all" the viewer could be a Foundation or
  // a Higher student, so neither paper's number is the "right" one to
  // show any more than it is under Crossover tier itself. The "all"
  // button's data-tier value is lowercase (unlike "Foundation",
  // "Higher" and "Crossover"), so this must match that case exactly.
  if((state.tier==="Crossover" || state.tier==="all") && q.crossoverQimg) return q.crossoverQimg;
  return q.qimg;
}
function qBodyHTML(q, modal){
  if(q.qimg){
    const qimg = selectQimg(q);
    const K = modal ? MODAL_CROP_SCALE : 0.5;
    const cls = modal ? 'q-diagram q-crop q-crop-modal' : 'q-diagram q-crop';
    const w = Math.round(qimg.w * K);
    const img = `<img src="${QIMG_BASE_PATH}${qimg.src}.png" alt="Question ${displayN(q)}, cropped directly from the original exam paper" style="width:${w}px;max-width:100%;">`;
    // A tiny number of crops have a hairline rule (e.g. a square root's
    // overline) that's proven unreliable as baked-in image pixels in some
    // environments even though the underlying file is correct - as a
    // guaranteed-robust fallback, those get the line ALSO drawn as a real
    // CSS border, positioned by the known fractional coordinates within
    // the image. A browser-drawn border can't suffer whatever image-decode
    // quirk affects the bitmap, since it isn't decoded from image data at all.
    let overlayHTML = '';
    let wrapOpen = '', wrapClose = '';
    if(qimg.overlays && qimg.overlays.length){
      const h = Math.round(qimg.h * K);
      wrapOpen = `<div style="position:relative;display:inline-block;width:${w}px;">`;
      wrapClose = `</div>`;
      overlayHTML = qimg.overlays.map(o => {
        const top = Math.round(o.yFrac * h);
        const left = Math.round(o.x0Frac * w);
        const right = Math.round((1 - o.x1Frac) * w);
        return `<div style="position:absolute;top:${top}px;left:${left}px;right:${right}px;border-top:2px solid #000;"></div>`;
      }).join('');
    }
    if(qimg.needsHeading){
      // Later parts (e.g. part (b) onwards) don't have their own number
      // baked into the crop - the numeral only appears once, on the first
      // part - so just the bare question number sits to the left of the
      // image here, the same way it sits to the left of question text on
      // the actual exam paper.
      // Modal is deliberately larger than the grid card's number, not just
      // proportionally scaled with K - it needs to read clearly as a
      // question number in its own right at that bigger size. Both are
      // nudged up slightly from directly-top-aligned to sit closer to
      // where the image's own first line of text visually starts.
      // Left blank whenever the image actually being shown for this
      // question is the crossover-masked crop (qimg, from selectQimg
      // above, IS q.crossoverQimg) - neither paper's number is the
      // "right" one to show in that case, and that applies just as much
      // to this externally-drawn heading as it does to a number baked
      // into the image itself. Deliberately NOT keyed off state.tier
      // directly: an ordinary (non-crossover) later part also has
      // needsHeading true, and under the unfiltered "all" view that
      // question's own number must still show - only an actual
      // crossover question's number gets blanked.
      // The row/column structure is kept (an empty span, not a removed
      // one) so the image doesn't shift sideways from losing its number
      // gutter.
      const fontSize = modal ? 18 : 12;
      const topNudge = modal ? 4 : 2;
      const numberText = (qimg === q.crossoverQimg) ? '' : baseQuestionNumber(q);
      return `<div class="q-part-row"><span class="q-part-number" style="font-size:${fontSize}px;margin-top:${topNudge}px;">${numberText}</span><div class="${cls}">${wrapOpen}${img}${overlayHTML}${wrapClose}</div></div>`;
    }
    return `<div class="${cls}">${wrapOpen}${img}${overlayHTML}${wrapClose}</div>`;
  }
  return `
    ${q.intro?`<div class="q-text">${mathText(q.intro)}</div>`:''}
    ${q.svg?`<div class="q-diagram">${enlargeImg(q.svg,1.35)}</div>`:''}
    ${q.text?`<div class="q-text">${mathText(q.text)}</div>`:''}
  `;
}
function qHeadingHTML(q){
  if(q.qimg){
    // A later part's number (if any) is now shown inline to the left of
    // the image via qBodyHTML, not as a separate heading block above it.
    return '';
  }
  return `<h4 class="q-heading">Question ${displayN(q)}</h4>`;
}

function questionCardHTML(q, showAnswer){
  return `
    ${qHeadingHTML(q)}
    ${qBodyHTML(q, true)}
    ${showAnswer?`<div class="answer-box"><strong>Answer:</strong> ${mathText(q.answer)}<hr style="border:none;border-top:1px solid var(--card-border);margin:10px 0;"><strong>Mark scheme:</strong><br>${mathMarkscheme(q.markscheme)}</div>`:''}
  `;
}

